//! 🧪️ Pending command metadata preserves its two original map roots and original strong caller through denial and token cancellation.
use super::*;
use semio_framework_plugin_command::command_admission::original_typed_command::OriginalTypedCommandSource as Source;
use semio_framework_plugin_decl_emission::ActionMeta;
use std::mem::size_of;
type App=fixture::NativeWindowApp;
#[track_caller]
fn action<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
#[test]
fn original_typed_command_source_retains_metadata_caller_and_selected_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,maximum_release_bytes:16<<20,maximum_depth:4096};
 for cut in law["cancelAfter"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize)).chain([None]){
  let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut source=Source::<App>::default();let mut view=semio_framework::ViewModel::new(semio_framework_ui_locale::Locale::En,semio_framework_ui_locale::Terminology::Native);view.active_mode_id=Some("v".repeat(law["wideTextBytes"].as_u64().unwrap()as usize));view.active_utility_by_window_id.insert("window".into(),"original utility".into());view.tool_run_trace_cursor_by_window_id.insert("window".into(),semio_framework_tool_run::ToolRunTraceCursor{generation:13,page:17,run:23});let text=view.active_mode_id.as_ref().unwrap().as_ptr();let utility=view.active_utility_by_window_id.get("window").unwrap().as_ptr();let mut metadata=Some(ActionMeta{actor:"original pending actor".into(),instance_id:71,view_state:Some(view)});
  for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:size_of::<Source<App>>()-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{action(&mut caller,&mut decoder,denied,|cx|{assert!(!source.admit(cx)?);Ok(())});assert!(!source.pending());}
  for index in 0..16{if cut==Some(index){caller.cancel().cancel_now();break}let ready=action(&mut caller,&mut decoder,g,|cx|{if !source.admit(cx)?{return Ok(false)}source.capture_metadata(&mut metadata,cx)});if ready{break}assert!(index<15)}
  if cut.is_none(){assert!(metadata.is_none());let view=source.metadata().unwrap().view_state.as_ref().unwrap();assert_eq!(view.active_mode_id.as_ref().unwrap().as_ptr(),text);assert_eq!(view.active_utility_by_window_id.get("window").unwrap().as_ptr(),utility);let mut foreign=OriginalJobDecodeOwner::empty();action(&mut caller,&mut foreign,g,|cx|{assert!(source.close_step(cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());}
  for index in 0..262144{if !source.pending(){break}let d=source.close_demands().unwrap();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}action(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|source.close_step(cx)));assert_eq!(caller.receipt(),RetainedCloneProgress::default(),"selected pending close accepted denied axis {axis}: {d:?}");assert_eq!(source.close_demands().unwrap(),d);}action(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|source.close_step(cx)));assert!(index<262143);}
  if let Some(metadata)=metadata{let mut metadata=Some(metadata);let mut close=semio_framework_value::retained_clone::RetainedCloneClose::default();for index in 0..262144{if metadata.is_none()&&close.is_empty(){break}action(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=close.next_owner_demands::<ActionMeta>(metadata.is_some(),&None,32768)?;close_original_retained_step(cx,d,|grant|{if let Some(step)=close.begin_granted(&mut metadata,grant)?{Ok(step)}else{close.select(32768)?.step(grant)}})?;Ok(())}));assert!(index<262143)}}
  while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 }
}
